"""TaskWeaver plugin: dominusnode_fetch (generated by dominusnode_taskweaver.generate_plugins)."""

from taskweaver.plugin import Plugin, register_plugin

from dominusnode_taskweaver.runtime import run


@register_plugin
class DominusNodeFetch(Plugin):
    def __call__(self, url, method=None, country=None, ip_class=None, session_id=None, allow_http=None) -> str:
        return run(self, "fetch", {"url": url, "method": method, "country": country, "ip_class": ip_class, "session_id": session_id, "allow_http": allow_http})
